namespace ForgeScope.Hub;

public static partial class Views
{
    static void Welcome(Page p)
    {
        p.Body.Append($"""
        <section class="welcome"><div class="eyebrow">FORGESCOPE</div>
        <h1>{p.T("Understand the problem. Choose your next step.", "Entenda o problema. Saiba por onde começar.", "Entiende el problema. Elige el siguiente paso.")}</h1>
        <p class="muted">{p.T("Connect a repository, upload a project or paste code. Review findings, source locations and next checks in one dashboard.", "Conecte um repositório, envie um projeto ou cole código. Veja os achados, as localizações e as próximas verificações em um único painel.", "Conecta un repositorio, sube un proyecto o pega código. Revisa los hallazgos, las ubicaciones y las siguientes comprobaciones en un panel.")}</p>
        <div class="actions"><a class="button primary" href="#start">{p.T("Start analysis", "Começar análise", "Iniciar análisis")}</a><a class="button" href="#demo">{p.T("See how it works", "Ver como funciona", "Ver cómo funciona")}</a></div></section>
        """);
    }
    static void SourceForms(Page p)
    {
        p.Body.Append($"""
        <section id="start"><h2>{p.T("What would you like to analyze?", "O que você quer analisar?", "¿Qué quieres analizar?")}</h2>
        <p>{p.T("Choose a source. Your results stay private to your account.", "Escolha uma origem. Os resultados ficam privados na sua conta.", "Elige un origen. Los resultados son privados para tu cuenta.")}</p>
        <div class="source-options"><article class="card"><span class="badge">GitHub</span><h3>{p.T("Your repositories", "Seus repositórios", "Tus repositorios")}</h3><p>{p.T("Choose a repository to investigate changes or monitor failed executions.", "Escolha um repositório para investigar mudanças ou acompanhar execuções com falha.", "Elige un repositorio para investigar cambios o seguir ejecuciones fallidas.")}</p><a class="button" href="/repositories?lang={p.Lang}">{p.T("Choose repository", "Escolher repositório", "Elegir repositorio")}</a></article>
        <article class="card"><span class="badge">ZIP</span><h3>{p.T("Upload your project folder", "Envie a pasta do projeto", "Sube la carpeta del proyecto")}</h3><p>{p.T("Compress your source folder as a .zip file and upload it here.", "Compacte a pasta do código em um arquivo .zip e envie aqui.", "Comprime la carpeta del código en un archivo .zip y súbelo aquí.")}</p>
        <form data-scan data-busy="{p.T("Analyzing…", "Analisando…", "Analizando…")}" method="post" action="/source" enctype="multipart/form-data">{p.Hidden()}<span>{p.T("Project ZIP", "ZIP do projeto", "ZIP del proyecto")}</span><div class="file-picker"><input id="project-zip" type="file" name="archive" accept=".zip,application/zip" required data-file-input data-file-status="zip-status" aria-label="{p.T("Project ZIP", "ZIP do projeto", "ZIP del proyecto")}"><label class="button" for="project-zip">{p.T("Choose file", "Escolher arquivo", "Elegir archivo")}</label><span id="zip-status" role="status" data-empty="{p.T("No file selected", "Nenhum arquivo selecionado", "Ningún archivo seleccionado")}">{p.T("No file selected", "Nenhum arquivo selecionado", "Ningún archivo seleccionado")}</span></div><button class="primary">{p.T("Analyze ZIP", "Analisar ZIP", "Analizar ZIP")}</button></form>
        <p class="upload-note">{p.T("Up to 3 MB compressed, 10 MB extracted and 250 files. Remove secrets and generated folders before uploading.", "Até 3 MB compactados, 10 MB extraídos e 250 arquivos. Remova segredos e pastas geradas antes do envio.", "Hasta 3 MB comprimidos, 10 MB extraídos y 250 archivos. Elimina secretos y carpetas generadas antes de subir.")}</p></article></div>
        <article class="card"><h3>{p.T("Or paste your code", "Ou cole seu código", "O pega tu código")}</h3>
        <form data-scan data-busy="{p.T("Analyzing…", "Analisando…", "Analizando…")}" method="post" action="/source">{p.Hidden()}<label>{p.T("File name with extension", "Nome do arquivo com extensão", "Nombre del archivo con extensión")}<input name="filename" placeholder="src/example.py" maxlength="200" required></label><label>{p.T("Source code", "Código-fonte", "Código fuente")}<textarea name="code" rows="8" maxlength="200000" required spellcheck="false"></textarea></label><button class="primary">{p.T("Analyze code", "Analisar código", "Analizar código")}</button></form></article>
        <p class="upload-note">{p.T("Source files are processed temporarily and deleted after analysis. Findings may contain code excerpts. No project code, builds or tests are executed. General repository checks work across languages; semantic dependency analysis currently covers Java and C#.", "Os arquivos são processados temporariamente e excluídos após a análise. Os achados podem conter trechos de código. O projeto, builds e testes não são executados. As verificações gerais atendem várias linguagens; a análise semântica de dependências cobre Java e C# atualmente.", "Los archivos se procesan temporalmente y se eliminan después del análisis. Los hallazgos pueden contener fragmentos de código. No se ejecutan el proyecto, builds ni pruebas. Las comprobaciones generales cubren varios lenguajes; el análisis semántico de dependencias cubre Java y C# actualmente.")}</p></section>
        """);
    }
    static void Tour(Page p)
    {
        p.Body.Append($"""
        <section id="demo" class="card"><span class="badge">{p.T("Interactive guided tour", "Tour guiado interativo", "Tour guiado interactivo")}</span><h2>{p.T("Learn the whole workflow, step by step", "Conheça o fluxo completo, passo a passo", "Conoce el flujo completo, paso a paso")}</h2><p>{p.T("A seven-step walkthrough with a practice diagnosis, progress and next/back controls. You can explore it before signing in. Example results are labeled and never modify your projects.", "Um percurso de sete etapas com diagnóstico para praticar, progresso e controles de avançar e voltar. Explore antes de entrar. Os resultados são exemplos identificados e não alteram seus projetos.", "Siete pasos con diagnóstico de práctica, progreso y controles. Puedes explorar antes de entrar; los ejemplos no modifican tus proyectos.")}</p><button type="button" class="primary" data-tour-start>{p.T("Start interactive tour", "Iniciar tour interativo", "Iniciar tour interactivo")}</button><noscript><p>{p.T("Enable JavaScript to use the interactive tour. Module explanations remain available above.", "Ative o JavaScript para usar o tour interativo. As explicações dos módulos continuam disponíveis acima.", "Activa JavaScript para el tour. Las explicaciones siguen disponibles arriba.")}</p></noscript></section>
        <dialog id="guided-tour" class="tour-dialog" aria-labelledby="tour-heading"><div class="actions"><strong id="tour-heading" data-tour-focus tabindex="-1">{p.T("ForgeScope guided tour", "Tour guiado do ForgeScope", "Tour guiado de ForgeScope")}</strong><button type="button" data-tour-close>{p.T("Close tour", "Fechar tour", "Cerrar tour")}</button></div><progress class="tour-progress" value="1" max="7" aria-label="{p.T("Tour progress", "Progresso do tour", "Progreso del tour")}"></progress><p data-tour-counter aria-live="polite">1 / 7</p>
        <section data-tour-step data-target="#modules"><h2>1 · {p.T("Understand the modules", "Entenda os módulos", "Entiende los módulos")}</h2><p>{p.T("PatchScope reviews changes; CIFuse groups CI diagnostics; RepoRelief checks repository maintenance; DevRescue explains recognizable failures; RevScope suggests investigation tools; Exports preserves the report. PlanRelay records the correction plan and its review.", "PatchScope revisa mudanças; CIFuse agrupa diagnósticos de CI; RepoRelief verifica manutenção; DevRescue explica falhas reconhecíveis; RevScope indica ferramentas; Exports preserva o relatório. PlanRelay registra o plano de correção e sua revisão.", "PatchScope revisa cambios; CIFuse agrupa diagnósticos; RepoRelief revisa mantenimiento; DevRescue explica fallos; RevScope recomienda herramientas; Exports preserva el informe. PlanRelay registra el plan y su revisión.")}</p><p class="muted">{p.T("The modules produce evidence and next checks. They do not guarantee a fix or automatically merge code.", "Os módulos produzem evidências e próximas verificações. Não garantem uma correção nem fazem merge automático.", "Los módulos producen evidencia y comprobaciones; no garantizan correcciones ni fusionan código.")}</p></section>
        <section data-tour-step data-target="#start" hidden><h2>2 · {p.T("Choose your source", "Escolha a origem", "Elige el origen")}</h2><p>{p.T("GitHub: select an accessible repository and optionally a PR or workflow execution. ZIP: compress the source folder, without generated files or secrets. Pasted code: include the file name and extension so the analyzer can identify it. Local input does not require a commit SHA.", "GitHub: selecione um repositório acessível e, opcionalmente, um PR ou execução. ZIP: compacte a pasta de código sem arquivos gerados ou segredos. Código colado: informe nome e extensão para identificar o arquivo. Entradas locais não exigem SHA de commit.", "GitHub: elige un repositorio y opcionalmente PR o ejecución. ZIP: comprime código sin secretos. Código pegado: indica nombre y extensión. La entrada local no requiere SHA.")}</p><p>{p.T("Limits: 3 MB ZIP, 10 MB extracted, 250 files; pasted code up to 200 KB. Signing in keeps the derived report private to your account.", "Limites: ZIP de 3 MB, 10 MB extraídos, 250 arquivos; código colado de até 200 KB. O login mantém o relatório derivado privado na sua conta.", "Límites: ZIP de 3 MB, 10 MB extraídos y 250 archivos; código pegado hasta 200 KB.")}</p></section>
        <section data-tour-step hidden><h2>3 · {p.T("Understand the analysis", "Entenda a análise", "Entiende el análisis")}</h2><p>{p.T("The server reads the supplied files, runs static checks and saves derived findings. It does not execute your project or its tests. ZIP source files are temporary. The report identifies which engines ran, were skipped or have limited coverage.", "O servidor lê os arquivos, faz verificações estáticas e salva achados derivados. Não executa o projeto nem os testes. Os arquivos do ZIP são temporários. O relatório mostra quais mecanismos rodaram, foram ignorados ou têm cobertura limitada.", "El servidor lee archivos, hace comprobaciones estáticas y guarda hallazgos. No ejecuta el proyecto ni pruebas. El informe muestra cobertura y límites.")}</p><p>{p.T("A Python snippet is not a complete repository: missing README, license and CI are not reported as snippet problems. Java and C# have dedicated semantic engines; other language coverage is explicitly limited.", "Um trecho Python não é um repositório completo: falta de README, licença e CI não vira problema do trecho. Java e C# têm mecanismos semânticos dedicados; a cobertura das outras linguagens é indicada como limitada.", "Un fragmento Python no es un repositorio: no se avisa por README, licencia o CI ausentes. La cobertura por lenguaje es explícita.")}</p></section>
        <section data-tour-step hidden><h2>4 · {p.T("Practice reading an error", "Pratique a leitura de um erro", "Practica la lectura de un error")}</h2><span class="badge">{p.T("Example data", "Dados de exemplo", "Datos de ejemplo")}</span><p>{p.T("Two messages came from one failed step. Which gives you a useful lead? Select a message.", "Duas mensagens vieram da mesma etapa com falha. Qual ajuda a investigar? Selecione uma mensagem.", "Dos mensajes vienen del mismo paso fallido. ¿Cuál ayuda a investigar? Selecciona uno.")}</p><div class="actions"><button type="button" data-demo-choice="exit" aria-pressed="false">Exit code 1</button><button type="button" data-demo-choice="429" aria-pressed="false">HTTP 429</button></div><div data-demo-result="exit" hidden class="demo-result"><strong>{p.T("Status only", "Apenas um estado", "Solo un estado")}</strong><p>{p.T("Exit code 1 confirms failure but does not explain its cause. Read related diagnostics before editing code.", "Exit code 1 confirma a falha, mas não explica a causa. Leia os diagnósticos relacionados antes de alterar código.", "Exit code 1 confirma el fallo, pero no explica la causa.")}</p></div><div data-demo-result="429" hidden class="demo-result"><strong>{p.T("A specific diagnostic", "Um diagnóstico específico", "Un diagnóstico específico")}</strong><p>{p.T("Dependency download HTTP 429 means the service reported a request limit. Check dependency caching and retry/backoff. It does not prove a source-code bug. File and line stay unknown if no trustworthy source location was supplied.", "Dependency download HTTP 429 significa que o serviço informou limite de requisições. Confira cache de dependências e novas tentativas com espera. Isso não comprova bug no código. Arquivo e linha ficam desconhecidos quando não há localização confiável.", "HTTP 429 indica un límite de solicitudes. Revisa caché y reintentos; no demuestra un fallo de código.")}</p></div></section>
        <section data-tour-step hidden><h2>5 · {p.T("Use a relevant tool", "Use uma ferramenta pertinente", "Usa una herramienta pertinente")}</h2><p>{p.T("RevScope connects artifact evidence to tools: a .pcap may suggest Wireshark; an APK may suggest JADX; an executable may suggest Detect It Easy and Ghidra. A recommendation shows the project, file and format evidence. An extension alone does not confirm the format or malicious behavior.", "O RevScope liga artefatos às ferramentas: .pcap pode indicar Wireshark; APK pode indicar JADX; executável pode indicar Detect It Easy e Ghidra. A recomendação mostra projeto, arquivo e evidência do formato. Uma extensão sozinha não confirma formato nem comportamento malicioso.", "RevScope conecta artefactos a herramientas: .pcap sugiere Wireshark, APK sugiere JADX y ejecutables sugieren Ghidra. La extensión no confirma el formato ni conducta maliciosa.")}</p><p>{p.T("Read DevRescue next checks for recognizable failures. The tools remain suggestions; nothing is installed or executed automatically.", "Leia as próximas verificações do DevRescue para falhas reconhecíveis. As ferramentas são sugestões: nada é instalado ou executado automaticamente.", "Lee las comprobaciones de DevRescue. No se instala ni ejecuta nada automáticamente.")}</p></section>
        <section data-tour-step hidden><h2>6 · {p.T("Connect your notifications", "Conecte suas notificações", "Conecta tus notificaciones")}</h2><p>{p.T("The Notification dashboard has your GitHub inbox first: PRs, issues, mentions and review activity returned for your account. If permission is missing, use Authorize GitHub notifications and review GitHub consent. It does not mark threads as read automatically.", "O Painel de Notificações mostra primeiro sua caixa do GitHub: PRs, issues, menções e revisões da sua conta. Se faltar permissão, use Autorizar notificações do GitHub e revise o consentimento no GitHub. Os tópicos não são marcados como lidos automaticamente.", "El panel muestra primero tu bandeja de GitHub. Si falta permiso, usa Autorizar notificaciones y revisa el consentimiento.")}</p><p>{p.T("Below it, add repositories to CI monitoring and synchronize. These are separate findings, with their original execution and commit. Polling runs every two minutes only while the server and session are active.", "Abaixo, adicione repositórios ao monitoramento de CI e sincronize. São achados separados, com execução e commit originais. A consulta automática ocorre a cada dois minutos enquanto servidor e sessão estiverem ativos.", "Más abajo añade repositorios a CI. La consulta automática ocurre cada dos minutos con servidor y sesión activos.")}</p></section>
        <section data-tour-step hidden><h2>7 · {p.T("Review, export and start", "Revise, exporte e comece", "Revisa, exporta y empieza")}</h2><p>{p.T("Record a correction plan, review its patch and resolve blockers. GitHub-linked investigations can use an explicitly configured trusted runner for before/after tests; a report alone is not test validation. Export the full investigation as JSON, or the findings as Markdown and SARIF.", "Registre um plano, revise o patch e resolva bloqueios. Investigações ligadas ao GitHub podem usar um executor confiável configurado explicitamente para testar antes/depois; um relatório sozinho não valida testes. Exporte a investigação completa em JSON ou os achados em Markdown e SARIF.", "Registra un plan, revisa el parche y resuelve bloqueos. Un informe no valida pruebas. Exporta la investigación como JSON; el analizador también admite Markdown y SARIF.")}</p><p>{p.T("Finish closes this practice tour. Choose a real input on Overview to start your own analysis.", "Concluir fecha este tour de prática. Escolha uma entrada real na Visão geral para iniciar sua análise.", "Finalizar cierra el tour. Elige una entrada real para iniciar tu análisis.")}</p></section>
        <div class="actions"><button type="button" data-tour-back>{p.T("Back", "Voltar", "Volver")}</button><button type="button" class="primary" data-tour-next data-next="{p.T("Next", "Avançar", "Siguiente")}" data-finish="{p.T("Finish tour", "Concluir tour", "Finalizar tour")}">{p.T("Next", "Avançar", "Siguiente")}</button></div></dialog>
        """);
    }
}
